def calculate_a_k(n, a0, k_max):
    a = a0
    results = {0: a}
    for k in range(1, k_max + 1):
        if k == 1:
            a_k = a + 1
        else:
            # a_k = a_{k-1}/k + k^(n-1)
            # Check if division is integer
            if a % k != 0:
                # This should not happen if a is chosen correctly for previous steps
                # but used for testing the sequence stability
                a_k = None 
            else:
                a_k = a // k + k**(n-1)

        # Check if the required condition a_{k-1} % k == 0 is met for k >= 2
        if k >= 2 and (results[k-1] % k != 0):
            print(f"Failure at k={k}: a_{k-1}={results[k-1]} not divisible by {k}")
            return None

        results[k] = a_k
        a = a_k
    return results

