def solve():
    # The condition m_{k-1} = (k+1)m_k - k^{n-1}
    # or m_k = (m_{k-1} + k^{n-1}) / (k+1)
    # Let's see for which n we can find a sequence of integers m_k.
    # This is equivalent to m_{k-1} \equiv -k^{n-1} \pmod{k+1}
    # Since k \equiv -1 \pmod{k+1}, we need m_{k-1} \equiv -(-1)^{n-1} \pmod{k+1}
    # m_{k-1} \equiv (-1)^n \pmod{k+1}
    # Let's check n=1: m_{k-1} \equiv -1 \pmod{k+1}.
    # m_0 \equiv -1 \pmod 2, m_1 \equiv -1 \pmod 3, m_2 \equiv -1 \pmod 4, ...
    # This is satisfied by m_k = -(k+1) + 1 = -k? No, m_k \equiv -1 \pmod{k+2}.
    # m_k = (k+2)j - 1.
    # For n=1, m_{k-1} = (k+1)m_k - 1.
    # If m_k = (k+2)j - 1, then m_{k-1} = (k+1)((k+2)j - 1) - 1 = (k+1)(k+2)j - (k+1) - 1 = (k+1)(k+2)j - (k+2).
    # This is a multiple of k+1? No, it's (k+1)(k+2)j - (k+2).
    # For this to be $m_{k-1} = k j' - 1$, we need $m_{k-1} \equiv -1 \pmod k$.
    # $(k+1)(k+2)j - (k+2) \equiv (1)(2)j - 2 \equiv 2j-2 \pmod k$.
    # We need $2j-2 \equiv -1 \equiv k-1 \pmod k$.
    # This is not helping.
    # Let's just try a larger range of a0.
    for n in range(1, 11):
        found = False
        for a0 in range(1, 100000):
            m = a0
            possible = True
            for k in range(1, 15):
                m = (m + k**(n-1)) / (k+1)
                if m != int(m):
                    possible = False
                    break
            if possible:
                print(f"n={n} works with a0={a0}")
                found = True
                break
        if not found:
            print(f"n={n} does not work")

